  function updateFullness(){const stamp=Date.now();let changed=false,warning='',lost=[];caught.forEach(entry=>{const elapsed=Math.max(0,Math.min(stamp-(Number(entry.fullnessAt)||stamp),1000*60*180));if(elapsed){entry.fullness=Math.max(0,Math.round((Number(entry.fullness??100)-elapsed/6000)*10)/10);entry.fullnessAt=stamp;changed=true}const f=fish.find(v=>v.id===entry.id),name=fishName(f)||ui('물고기','Fish');if(entry.fullness<=0){if(!entry.starvingAt){entry.starvingAt=stamp;entry.hungerAlertLevel=3;warning=ui(`${name}이(가) 너무 배고파요! 2분 안에 먹이를 주세요.`,`${name} is starving! Feed it within 2 minutes.`);changed=true}else if(stamp-entry.starvingAt>=120000)lost.push(entry)}else if(entry.fullness<=18&&entry.hungerAlertLevel<2){entry.hungerAlertLevel=2;warning=ui(`${name}이(가) 몹시 배고파요! 수족관에서 먹이를 주세요.`,`${name} is very hungry! Feed it in the aquarium.`);changed=true}else if(entry.fullness<=35&&entry.hungerAlertLevel<1){entry.hungerAlertLevel=1;warning=ui(`${name}이(가) 배고파하기 시작했어요.`,`${name} is getting hungry.`);changed=true}});if(lost.length){const gone=new Set(lost.map(v=>v.seed));caught=caught.filter(v=>!gone.has(v.seed));warning=ui(`${lost.map(v=>fishName(fish.find(f=>f.id===v.id))||'물고기').join(', ')}이(가) 먹이를 못 먹어 무지개 바다로 떠났어요.`,`${lost.map(v=>fishName(fish.find(f=>f.id===v.id))||'Fish').join(', ')} could not eat and swam to the rainbow sea.`);changed=true;updateHud();if(mode==='aquarium')buildFeedTray()}if(warning&&!['bite','reel','aim','failure'].includes(mode))setNotice(warning);if(changed&&stamp-lastHungerSave>2500){lastHungerSave=stamp;save()}}
  function feedItems(){return inventory.map((entry,index)=>({entry,index,item:aquariumItems.find(v=>v.id===entry.id)})).filter(v=>v.item?.kind==='feed'&&v.entry.role==='feed')}
  function mostHungry(){return caught.slice().sort((a,b)=>(a.fullness??100)-(b.fullness??100))[0]}
  function buildFeedTray(){if(mode!=='aquarium')return;const foods=feedItems(),target=mostHungry();el.feedChoices.replaceChildren();if(!target||!foods.length){el.feedTray.classList.add('hidden');return}el.feedTray.classList.remove('hidden');el.feedHint.textContent=feeding?ui('맛있게 먹는 중이에요…','Enjoying a meal…'):ui(`가장 배고픈 ${fishName(fish.find(v=>v.id===target.id))||'물고기'}에게 주세요.`,`Feed ${fishName(fish.find(v=>v.id===target.id))||'the hungriest fish'} first.`);foods.forEach(({index,item})=>{const b=document.createElement('button');b.type='button';b.className='feed-choice';b.disabled=!!feeding;b.textContent=ui(`${itemName(item)} 주기`,`Feed ${itemName(item)}`);b.onclick=()=>startFeeding(index);el.feedChoices.append(b)})}
