  function updatePlayer(dt){let vx=0,vy=0;if(keys.ArrowLeft||keys.a)vx=-1;if(keys.ArrowRight||keys.d)vx=1;if(keys.ArrowUp||keys.w)vy=-1;if(keys.ArrowDown||keys.s)vy=1;if(vx||vy){player.targetX=player.x+vx*999;player.targetY=player.y+vy*999}const dx=player.targetX-player.x,dy=player.targetY-player.y,d=Math.hypot(dx,dy);if(d>2){player.direction=Math.abs(dx)>Math.abs(dy)?(dx<0?1:3):(dy<0?2:0);const k=Math.min(d,dt*(scene.portrait?.22:.13));player.x+=dx/d*k;player.y+=dy/d*k;const b=scene.portrait?{x1:90,x2:630,y1:760,y2:1140}:{x1:250,x2:810,y1:335,y2:477};player.x=Math.max(b.x1,Math.min(b.x2,player.x));player.y=Math.max(b.y1,Math.min(b.y2,player.y))}}
