  function bite(){mode='bite';const reward=chooseReward(fishing.bait);fishing.fish=reward.fish||null;fishing.item=reward.item||null;fishing.box=reward.box||null;fishing.biteEnd=now+3000;el.notice.textContent=ui('입질이다! 무엇이 걸렸을까요?','A bite! What could it be?');el.notice.classList.remove('hidden');el.action.className='action-button bite';el.action.textContent=ui('SPACE · 지금 낚아채기!','SPACE · Hook it now!');el.bar.innerHTML=ui('입질 유지 중! 3초 안에 버튼이나 Space를 한 번 누르세요.','Keep the bite! Press once within 3 seconds.');audio('bite')}
