  function sellFish(index){if(mode!=='aquarium'||feeding){setNotice(feeding?'먹이를 먹는 동안에는 판매할 수 없어요.':'수족관에서만 판매할 수 있어요.');return}const entry=caught[index],f=fish.find(v=>v.id===entry?.id);if(!f)return;const value=fishSaleValue(f);caught.splice(index,1);coins+=value;save();updateHud();buildSellChoices();buildFeedTray();setNotice(`${f.name}을(를) 판매해 ${value}코인을 받았어요!`);audio('catch')}
