  function catchLoot(){const item=fishing.item;if(timeAttack.running&&timeAttack.turnActive){timeAttackCatch({item});return}mode='harbor';el.meter.classList.remove('aim');el.meter.classList.add('hidden');el.action.className='action-button hidden';const rctx=el.resultCanvas.getContext('2d');rctx.clearRect(0,0,220,140);rctx.imageSmoothingEnabled=false;drawLoot(rctx,item,110,72,2.35);el.resultEye.textContent=item.kind==='feed'?'NEW BAIT OR FEED':'NEW AQUARIUM DECOR';el.resultTitle.textContent=ui(`${itemName(item)}을 건졌다!`,`You found ${itemName(item)}!`);if(item.kind==='feed'){pendingLoot=item;$('#backHarbor').textContent=ui('먹이로 보관','Store as Food');$('#openAquarium').textContent=ui('미끼로 보관','Store as Bait');el.resultCopy.textContent=ui(`${baitTierName(item.bait)} 미끼예요. 수족관 먹이로 보관하거나, ${baitChanceLabel(item.bait)} 미끼로 챙길 수 있어요.`,`${baitTierName(item.bait)} bait. Store it as aquarium food, or keep it as bait: ${baitChanceLabel(item.bait)}.`)}else{resetResultActions();inventory.push({id:item.id,role:'deco',seed:Math.floor(Math.random()*99999),caughtAt:Date.now()});save();updateHud();el.resultCopy.textContent=ui('수족관 안에 새 장식으로 바로 배치했어요.','The new decor is ready in your aquarium.')}el.result.classList.remove('hidden');setNotice(item.kind==='feed'?ui('어떻게 보관할지 선택하세요.','Choose how to store it.'):ui('수족관 장식을 보관했어요!','Aquarium decor stored!'));audio('catch')}
  function boxEntries(){return inventory.map((entry,index)=>({entry,index,box:randomBoxes.find(box=>box.id===entry.id)})).filter(v=>v.box&&v.entry.role==='box')}
  function drawBoxResult(box,eyebrow,title,copy,destination='boxes'){const rctx=el.resultCanvas.getContext('2d');rctx.clearRect(0,0,220,140);rctx.imageSmoothingEnabled=false;drawBox(rctx,box,110,72,.72);resetResultActions();resultDestination=destination;el.resultEye.textContent=eyebrow;el.resultTitle.textContent=title;el.resultCopy.textContent=copy;$('#openAquarium').innerHTML=destination==='aquarium'?'수족관에 전시 <span>→</span>':'상자 보관함 열기 <span>→</span>';el.result.classList.remove('hidden')}
  function catchBox(){const box=fishing.box;if(!box)return;const stamp=Date.now();inventory.push({id:box.id,role:'box',seed:Math.floor(Math.random()*99999),caughtAt:stamp});save();updateHud();mode='harbor';el.meter.classList.remove('aim');el.meter.classList.add('hidden');el.action.className='action-button hidden';drawBoxResult(box,'RARE SURPRISE BOX',`${box.name}을 건졌다!`,`희귀한 ${box.grade} 랜덤 상자예요. 열면 꽝·쓰레기·물고기 3마리·미끼 10개·장식 3개 중 하나가 나옵니다.`);setNotice('랜덤 상자를 보관함에 넣었어요!');audio('catch')}
  function rollBoxOutcome(box){const total=Object.values(box.outcomes).reduce((sum,value)=>sum+value,0);let roll=Math.random()*total;return Object.keys(box.outcomes).find(key=>(roll-=box.outcomes[key])<=0)||'empty'}
  function randomBaitForBox(tier){const pool=aquariumItems.filter(item=>item.kind==='feed'&&item.bait<=tier);return pool[Math.floor(Math.random()*pool.length)]||aquariumItems[0]}
  function openBoxAt(index){const entry=inventory[index],box=randomBoxes.find(v=>v.id===entry?.id);if(!box)return;inventory.splice(index,1);const stamp=Date.now(),outcome=rollBoxOutcome(box);let title,copy,destination='boxes';if(outcome==='fish'){const prizes=Array.from({length:3},()=>chooseWeighted(box.tier));prizes.forEach(f=>caught.push({id:f.id,seed:Math.floor(Math.random()*99999),caughtAt:stamp,fullness:100,fullnessAt:stamp}));title='물고기 3마리 획득!';copy=prizes.map(f=>f.name).join(' · ');destination='aquarium'}else if(outcome==='bait'){const prizes=Array.from({length:10},()=>randomBaitForBox(box.tier));prizes.forEach(item=>inventory.push({id:item.id,role:'bait',seed:Math.floor(Math.random()*99999),caughtAt:stamp}));title='미끼 10개 획득!';copy=`${baitTierName(box.tier)} 등급까지의 미끼 10개를 미끼 보관함에 넣었어요.`}else if(outcome==='decor'){const pool=aquariumItems.filter(item=>item.kind==='deco'),prizes=Array.from({length:3},()=>pool[Math.floor(Math.random()*pool.length)]);prizes.forEach(item=>inventory.push({id:item.id,role:'deco',seed:Math.floor(Math.random()*99999),caughtAt:stamp}));title='장식 3개 획득!';copy=prizes.map(item=>item.name).join(' · ')}else if(outcome==='trash'){title='쓰레기만 나왔어요…';copy='젖은 깡통과 해초 뭉치뿐이었어요. 다음 상자를 노려보세요.'}else{title='아쉽게도 꽝!';copy='상자가 텅 비어 있었어요. 희귀 상자는 언제나 좋은 것만 주지는 않아요.'}save();updateHud();buildBoxChoices();el.boxOverlay.classList.add('hidden');drawBoxResult(box,'SURPRISE BOX OPEN',title,copy,destination);if(outcome==='trash'){const rctx=el.resultCanvas.getContext('2d');rctx.clearRect(0,0,220,140);drawContained(rctx,images.trashReward,18,7,184,126)}setNotice(title);audio(outcome==='fish'||outcome==='bait'||outcome==='decor'?'catch':'fail')}
  function buildBoxChoices(){const boxes=boxEntries();el.boxChoices.replaceChildren();if(!boxes.length){el.boxHint.textContent='아직 보관한 랜덤 상자가 없어요. 미끼를 사용해 낚시하면 아주 드물게 건질 수 있어요.';return}el.boxHint.textContent=`보관 중인 랜덤 상자 ${boxes.length}개. 개봉하면 결과가 바로 확정돼요.`;boxes.forEach(({index,box})=>{const b=document.createElement('button'),img=document.createElement('img'),copy=document.createElement('span'),small=document.createElement('small');b.type='button';b.className=`box-choice grade-${box.grade}`;img.src=box.src;img.alt='';copy.textContent=box.name;small.textContent=`${box.grade} · 열어 보기`;copy.append(small);b.append(img,copy);b.onclick=()=>openBoxAt(index);el.boxChoices.append(b)})}
  function openBoxPouch(){buildBoxChoices();el.boxOverlay.classList.remove('hidden')}
  function storePendingLoot(role){if(!pendingLoot)return false;const item=pendingLoot;inventory.push({id:item.id,role,seed:Math.floor(Math.random()*99999),caughtAt:Date.now()});save();updateHud();resetResultActions();el.result.classList.add('hidden');mode='harbor';setNotice(role==='bait'?`${item.name}을(를) 미끼 보관함에 넣었어요!`:`${item.name}을(를) 먹이 보관함에 넣었어요!`);return true}
  function fail(reason='time'){if(!['bite','reel','aim'].includes(mode))return;const rush=timeAttack.running&&timeAttack.turnActive;mode='failure';fishing.failureReason=reason;el.notice.classList.add('hidden');el.meter.classList.remove('aim');el.meter.classList.add('hidden');el.action.className='action-button hidden';el.bar.innerHTML=rush?ui('놓쳤어요! 다음 입질을 빠르게 노려보세요.','Escaped! Quickly try for the next bite.'):ui(reason==='range'?'<b>놓쳤어요!</b> 노란 칸 밖에서 멈췄어요. 물고기가 낚시꾼을 꿀꺽!':'<b>줄이 풀렸어요!</b> 시간이 지나 물고기가 낚시꾼을 꿀꺽!',reason==='range'?'<b>It escaped!</b> You stopped outside the yellow zone.':'<b>The line slipped!</b> Time ran out and the fish gulped the fisher.');setTimeout(()=>{mode='harbor';const p=scene.portrait?{x:500,y:960}:{x:610,y:425};player.x=p.x;player.y=p.y;player.targetX=p.x;player.targetY=p.y;if(rush&&timeAttack.running&&timeAttack.turnActive)castTimeAttackLine();else setNotice(ui('괜찮아요! 슬라이더 속도와 노란 칸을 보고 다시 도전해요.','Try again! Watch the slider speed and yellow zone.'))},rush?900:1750);audio('fail')}
  function buyTheme(theme){if(themeUnlocked(theme)){selectedTheme=theme;save();setNotice(ui(`${themeName(theme)} 전시관으로 바꿨어요!`,`Switched to the ${themeName(theme)} aquarium!`));return}if(coins<theme.price){setNotice(ui(`${theme.price-coins}코인이 더 필요해요. 물고기를 판매해 보세요!`, `You need ${theme.price-coins} more coins. Try selling a fish!`));return}coins-=theme.price;ownedThemes.push(theme.id);selectedTheme=theme;save();updateHud();setNotice(ui(`${themeName(theme)} 전시관을 구매했어요!`,`Bought the ${themeName(theme)} aquarium!`));audio('catch')}
  function baitShopPrice(item){return [0,24,38,64][item.bait]||24}
  function baitGlyph(item){return item.bait===3?'✨':item.bait===2?'🦐':'🪱'}
  function buyShopBait(item){const price=baitShopPrice(item);if(coins<price){setNotice(ui(`${price-coins}코인이 더 필요해요.`, `You need ${price-coins} more coins.`));return}coins-=price;inventory.push({id:item.id,role:'bait',seed:Math.floor(Math.random()*99999),caughtAt:Date.now()});save();updateHud();renderShop();setNotice(ui(`${itemName(item)} 미끼를 샀어요!`,`Bought ${itemName(item)} bait!`));audio('catch')}
  function renderShop(){el.shopCoinCount.textContent=coins;el.shopTabs.querySelectorAll('button').forEach(button=>button.classList.toggle('selected',button.dataset.shopTab===shopTab));el.shopChoices.replaceChildren();if(shopTab==='themes'){el.shopHint.textContent=ui('전시관을 구매해 수족관을 멋지게 꾸며보세요.','Buy aquarium themes and make your exhibit shine.');aquariumThemes.forEach(theme=>{const owned=themeUnlocked(theme),b=document.createElement('button'),img=document.createElement('img'),copy=document.createElement('span'),price=document.createElement('strong');b.type='button';b.className=`shop-choice${!owned&&coins<theme.price?' unaffordable':''}`;img.src=theme.src;img.alt='';copy.innerHTML=`<b>T${theme.tier} · ${themeName(theme)}</b><small>${owned?(theme.id===selectedTheme.id?ui('현재 사용 중','In use'):ui('보유한 전시관','Owned aquarium')):ui('수족관 테마','Aquarium theme')}</small>`;price.textContent=owned?ui('선택','Select'):`${theme.price} ${ui('코인','coins')}`;b.append(img,copy,price);b.onclick=()=>{buyTheme(theme);renderShop()};el.shopChoices.append(b)})}else{el.shopHint.textContent=ui('좋은 미끼일수록 큰 물고기를 만나기 쉬워요. 사면 바로 미끼 가방에 들어가요.','Better bait makes bigger fish easier to meet. Bought bait goes straight into your pouch.');aquariumItems.filter(item=>item.kind==='feed').forEach(item=>{const price=baitShopPrice(item),b=document.createElement('button'),icon=document.createElement('span'),copy=document.createElement('span'),cost=document.createElement('strong');b.type='button';b.className=`shop-choice${coins<price?' unaffordable':''}`;icon.className='bait-icon';icon.textContent=baitGlyph(item);copy.innerHTML=`<b>${itemName(item)}</b><small>${baitTierName(item.bait)} ${ui('미끼','bait')} · ${baitChanceLabel(item.bait)}</small>`;cost.textContent=`${price} ${ui('코인','coins')}`;b.append(icon,copy,cost);b.onclick=()=>buyShopBait(item);el.shopChoices.append(b)})}el.shopDialogueText.textContent=shopTab==='themes'?ui('수족관은 코인으로 하나씩 살 수 있단다. 마음에 드는 전시관을 골라 봐!','You can buy aquariums one at a time with coins. Pick the exhibit you like!'):ui('미끼가 좋을수록 큰 물고기를 만나기 쉬워진단다. 필요한 만큼 챙겨 가렴!','Better bait makes bigger fish easier to meet. Take what you need!')}
  function openShop(){if(!['harbor','shop','menu'].includes(mode)||timeAttack.running){setNotice(ui('낚시와 타임 어택이 끝난 뒤 상점에 갈 수 있어요.','Visit the shop after fishing or Time Attack ends.'));return}if(!el.result.classList.contains('hidden')){setNotice(ui('보상을 먼저 확인한 뒤 상점에 가요.','Check your reward before visiting the shop.'));return}const shopkeeper=el.shopDialogue.querySelector('img');if(!shopkeeper.getAttribute('src'))shopkeeper.src=shopkeeper.dataset.src;clearNavigationOverlays();mode='shop';shopTab='themes';el.notice.classList.add('hidden');el.feedTray.classList.add('hidden');el.shopWindow.classList.remove('hidden');el.shopDialogue.classList.remove('hidden');renderShop()}
  function leaveShop(){mode='harbor';el.shopWindow.classList.add('hidden');el.shopDialogue.classList.add('hidden');setNotice(ui('상점 구경을 마쳤어요.','Finished browsing the shop.'))}
  function buildThemeChoices(){el.themeChoices.replaceChildren();el.themeHint.textContent=ui(`보유 코인 ${coins} · 물고기를 판매해 더 화려한 전시관을 구매하세요.`,`Coins ${coins} · Sell fish to buy brighter aquarium themes.`);aquariumThemes.forEach(theme=>{const unlocked=themeUnlocked(theme),affordable=coins>=theme.price,b=document.createElement('button'),img=document.createElement('img'),copy=document.createElement('span'),small=document.createElement('small');b.type='button';b.className=`theme-choice tier-${theme.tier}${theme.id===selectedTheme.id?' selected':''}${unlocked?'':' locked'}${!unlocked&&!affordable?' unaffordable':''}`;img.src=theme.src;img.alt='';copy.innerHTML=`<b>T${theme.tier} · ${themeName(theme)}</b>`;small.textContent=unlocked?(theme.id===selectedTheme.id?ui('현재 사용 중','In use'):ui('선택하기','Select')):(affordable?ui(`${theme.price}코인으로 구매`,`Buy for ${theme.price} coins`):ui(`${theme.price}코인 · ${theme.price-coins}코인 부족`,`${theme.price} coins · need ${theme.price-coins} more`));copy.append(small);b.append(img,copy);b.onclick=()=>{buyTheme(theme);updateHud();buildThemeChoices()};el.themeChoices.append(b)})}
  function openThemeGallery(){if(mode!=='aquarium')return;buildThemeChoices();el.themeOverlay.classList.remove('hidden')}
  function enterAquarium(){mode='aquarium';el.meter.classList.add('hidden');el.notice.classList.add('hidden');el.action.className='action-button';el.action.textContent=ui('← 항구로 돌아가기','← Back to Harbor');el.themeButton.classList.add('hidden');el.sellButton.classList.remove('hidden');buildFeedTray()}
  function updateHud(){const has=(kind,role)=>inventory.filter(entry=>{const item=aquariumItems.find(v=>v.id===entry.id);return item?.kind===kind&&(!role||entry.role===role)}).length;el.fishCount.textContent=Math.min(fish.length,new Set(caught.map(v=>v.id)).size);el.fishTotal.textContent=fish.length;el.coinCount.textContent=coins;el.caughtTotal.textContent=caught.length;el.baitCount.textContent=has('feed','bait');el.feedCount.textContent=has('feed','feed');el.decorCount.textContent=has('deco');el.boxCount.textContent=boxEntries().length;el.characterButton.querySelector('span').textContent=selectedPlayer.name;el.rodLabel.textContent=rodName(selectedRod)}
  function action(){if(timeAttack.running&&timeAttack.turnActive&&mode==='harbor'){castTimeAttackLine();return}if(mode==='harbor')startFishing();else if(mode==='waiting'||mode==='bite'||mode==='reel')reel();else if(mode==='aim')stopAim();else if(mode==='aquarium'){mode='harbor';feeding=null;el.feedTray.classList.add('hidden');el.themeButton.classList.add('hidden');el.sellButton.classList.add('hidden');setNotice(ui('항구로 돌아왔어요.','Back at the harbor.'))}else if(mode==='shop')leaveShop()}
  function tick(t){now=t;const dt=Math.min(40,t-last||16);last=t;updateTimeAttack();updateFullness();document.documentElement.classList.toggle('aquarium-active',mode==='aquarium');document.documentElement.classList.toggle('shop-active',mode==='shop');el.themeButton.classList.add('hidden');el.sellButton.classList.toggle('hidden',mode!=='aquarium');prepareCanvas();if(mode==='harbor'){updatePlayer(dt);drawHarbor()}else if(['waiting','bite','reel','aim','failure'].includes(mode)){drawFishing();if(mode==='waiting'&&now>fishing.biteAt)bite();if(mode==='bite'&&now>fishing.biteEnd)fail();if(mode==='reel'&&now>fishing.deadline)fail();if(mode==='aim'){updateAim();if(now>fishing.deadline)fail()}}else if(mode==='aquarium')drawAquarium();else if(mode==='shop')drawShop();else background(scene.portrait?images.harborPortrait:images.harbor);requestAnimationFrame(tick)}
  function showCharacterIntro(p){const intro=$('#characterIntro'),cv=$('#characterIntroCanvas'),cc=cv.getContext('2d');cc.clearRect(0,0,cv.width,cv.height);cc.imageSmoothingEnabled=true;drawContained(cc,p.portraitImg,10,0,148,188);$('#characterIntroName').textContent=p.name;$('#characterIntroText').textContent=characterDialogues[p.id]||'';intro.classList.remove('hidden')}
  function buildChoices(){
    const pWrap=$('#playerChoices'),pOverlay=$('#playerChoicesOverlay'),rodWrap=$('#rodChoices'),rodOverlay=$('#rodChoicesOverlay');
    pWrap.replaceChildren();pOverlay.replaceChildren();rodWrap.replaceChildren();rodOverlay.replaceChildren();
    function selectPlayer(p){selectedPlayer=p;save();updateHud();document.querySelectorAll('[data-player-id]').forEach(q=>q.classList.toggle('selected',q.dataset.playerId===p.id));$('#characterOverlay').classList.add('hidden');showCharacterIntro(p);setNotice(`${p.name}으로 낚시꾼을 바꿨어요!`)}
    function playerButton(p){const b=document.createElement('button'),img=document.createElement('img');b.type='button';b.dataset.playerId=p.id;b.className='selection player-selection'+(p.id===selectedPlayer.id?' selected':'');img.className='player-portrait';img.src=p.portraitSrc.replace('.png','.webp');img.alt=`${p.name} 정면 모습`;b.append(img,document.createTextNode(p.name));b.onclick=()=>selectPlayer(p);return b}
    function rodButton(r){const b=document.createElement('button'),cv=document.createElement('canvas'),cc=cv.getContext('2d'),label=document.createElement('span'),detail=document.createElement('small'),legend=fish.find(f=>f.id===r.legendId);b.type='button';b.dataset.rodId=r.id;b.classList.add('rod-selection');cv.width=128;cv.height=88;cc.imageSmoothingEnabled=false;drawRodPreview(cc,r.previewIndex,3,4,122,78);label.className='rod-choice-name';label.textContent=language==='en'?rodName(r).replace(' Rod',''):r.name.replace(' 낚싯대','');b.append(cv,label,detail);const paint=()=>{b.classList.toggle('selected',r.id===selectedRod.id);b.classList.remove('locked');detail.textContent=r.id===selectedRod.id?`✓ ${shortLegendName(legend)}`:shortLegendName(legend);b.title=language==='en'?`Signature legend: ${fishName(legend)}`:`전용 전설: ${fishName(legend)}`};b._paint=paint;paint();b.onclick=()=>{selectedRod=r;save();updateHud();document.querySelectorAll('[data-rod-id]').forEach(q=>q._paint?.());setNotice(language==='en'?`${rodName(r)} selected! You can meet ${fishName(legend)}.`:`${r.name} 선택! ${legend?.name||'전설 물고기'}을(를) 만날 수 있어요.`)};return b}
    players.forEach(p=>{pWrap.append(playerButton(p));pOverlay.append(playerButton(p))});rods.forEach(r=>{rodWrap.append(rodButton(r));rodOverlay.append(rodButton(r))})
  }
  rodSelectionPreview.addEventListener('load',()=>{if(assetsReady)buildChoices()});
  let timeAttackCount=1,timeAttackIds=[];
  function renderTimeAttackSetup(){const countWrap=$('#timeAttackCount'),playerWrap=$('#timeAttackPlayers'),start=$('#startTimeAttack');if(!timeAttackIds.length)timeAttackIds=[selectedPlayer.id];timeAttackIds=timeAttackIds.slice(0,timeAttackCount);countWrap.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',Number(b.dataset.count)===timeAttackCount));playerWrap.replaceChildren();players.forEach(p=>{const chosen=timeAttackIds.includes(p.id),b=document.createElement('button'),img=document.createElement('img');b.type='button';b.className='selection player-selection'+(chosen?' selected':'');b.disabled=!chosen&&timeAttackIds.length>=timeAttackCount;img.className='player-portrait';img.src=p.portraitSrc.replace('.png','.webp');img.alt=`${p.name} 정면 모습`;b.append(img,document.createTextNode(p.name));b.onclick=()=>{if(timeAttackIds.includes(p.id)){if(timeAttackIds.length>1)timeAttackIds=timeAttackIds.filter(id=>id!==p.id)}else if(timeAttackIds.length<timeAttackCount)timeAttackIds.push(p.id);renderTimeAttackSetup()};playerWrap.append(b)});start.disabled=timeAttackIds.length!==timeAttackCount}
